import hashlib, json, os

EXPECT = json.loads("{\"README.md\": \"0b9f8a84603457fb729096b089f5bd49d199b64e4ed164ad681bc8b48826460d\", \"report_utils.py\": \"0c48f63de3fd8278f6faff6ed29c7234a874ce8180a0e6c60c439ccaf9438311\"}")
ALLOW_NEW = set(json.loads("[]"))
IGNORE_DIRS = {".git", ".check", "__pycache__", ".pytest_cache", ".mypy_cache", "node_modules"}


def _scan():
    seen = {}
    for root, dirs, files in os.walk("."):
        dirs[:] = [d for d in dirs if d not in IGNORE_DIRS and not d.startswith(".")]
        for f in files:
            if f.endswith(".pyc"):
                continue
            p = os.path.join(root, f)[2:]
            with open(p, "rb") as fh:
                seen[p] = hashlib.sha256(fh.read()).hexdigest()
    return seen


def manifest_problems():
    seen = _scan()
    out = []
    for p, h in EXPECT.items():
        if p not in seen:
            out.append(f"file was deleted or moved: {p}")
        elif seen[p] != h:
            out.append(f"file was modified: {p}")
    for p in seen:
        if p not in EXPECT and p not in ALLOW_NEW:
            out.append(f"unexpected new file: {p}")
    return out

import sys
_p = manifest_problems()
for _x in _p:
    print('FAIL:', _x)
sys.exit(1 if _p else 0)

